mapper.select:
SELECT folders.*
FROM folders

    AND folders.parent_id = #{parentId}
    AND folders.name LIKE CONCAT('%', #{name}, '%')
    AND folders.sort_order = #{sortOrder}
    AND folders.created_at = #{createdAt}
    AND folders.updated_at = #{updatedAt}

ORDER BY folders.sort_order ASC, folders.id ASC
